// POC ONLY — poc/http-ingress-b — do not merge as production API.
//
// Thin wrapper around `createCombinedWorker` (same function
// `bin/node-red-temporal worker --role combined` uses) that additionally
// passes `captureOptions.timeoutMs`, which the CLI does not expose as a
// flag. This PoC's `delay` node intentionally runs the Capture pending
// entry well past `capture.js`'s DEFAULT_TIMEOUT_MS (5000ms) for B2/B3
// (5-30s delays), so the timeout must be raised. No file outside this poc/
// folder needed to change for this - `worker.js`'s existing
// `options.captureOptions` passthrough already supports it.
//
// Usage:
//   TEMPORAL_ADDRESS=127.0.0.1:7249 \
//   TEMPORAL_WORKFLOW_TASK_QUEUE=poc-http-ingress-b \
//   TEMPORAL_ACTIVITY_TASK_QUEUE=poc-http-ingress-b \
//   node run-worker.js

"use strict";

const path = require("path");
const { createCombinedWorker } = require("../../lib/worker");

const FLOW_PATH = process.env.POC_FLOW_PATH || path.join(__dirname, "flow.json");
const CAPTURE_TIMEOUT_MS = Number(process.env.POC_CAPTURE_TIMEOUT_MS || 60000);

async function main() {
    const result = await createCombinedWorker(FLOW_PATH, {
        captureOptions: { timeoutMs: CAPTURE_TIMEOUT_MS }
    });
    console.log(`[poc-worker] running, flowVersion=${result.flowVersion}, captureTimeoutMs=${CAPTURE_TIMEOUT_MS}`);

    process.on("SIGTERM", async () => {
        console.log("[poc-worker] received SIGTERM, shutting down...");
        try {
            await result.stop();
        } catch (err) {
            console.error("[poc-worker] error during shutdown:", err.message);
        }
        process.exit(0);
    });

    const runs = [result.worker.run()];
    if (result.workflowWorker) {
        runs.push(result.workflowWorker.worker.run());
    }
    await Promise.all(runs);
}

main().catch((err) => {
    console.error("[poc-worker] fatal:", err);
    process.exit(1);
});
